    // --- Unknown key detection tests ---

    #[test]
    fn parse_config_rejects_unknown_top_level_keys() {
        let content = "ap_name: MyApp\nsteps: {}";
        let result = parse_config(content, Path::new("test.yml"));
        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));

        let err = result.unwrap_err();
        let msg = err.to_string();
        assert!(msg.contains("ap_name"), "error should mention the unknown key: {}", msg);
    }

    #[test]
    fn parse_config_accepts_all_known_keys() {
        let content = r#"
app_name: Test
settings: {}
template_sources: []
steps: {}
workflows: {}
secrets: {}
extends: []
requirements: {}
vars: {}
"#;
        let result = parse_config(content, Path::new("test.yml"));
        assert!(result.is_ok(), "all known keys should be accepted: {:?}", result.err());
    }

    #[test]
    fn parse_config_still_allows_empty_content() {
        let content = "";
        let result = parse_config(content, Path::new("test.yml"));
        assert!(result.is_ok(), "empty config should still be valid");
    }

    #[test]
    fn parse_config_error_lists_all_unknown_keys() {
        let content = "ap_name: Test\nstepz: {}\nunknown_field: 42";
        let result = parse_config(content, Path::new("test.yml"));
        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));

        let msg = result.unwrap_err().to_string();
        assert!(msg.contains("ap_name"), "should list ap_name: {}", msg);
        assert!(msg.contains("stepz"), "should list stepz: {}", msg);
        assert!(msg.contains("unknown_field"), "should list unknown_field: {}", msg);
